class Vehicle {}
class Car extends Vehicle {}
class Taxi extends Car {}
class Bike extends Vehicle {}

const taxi = new Taxi();
const car = new Car();

console.log(taxi instanceof Vehicle);
console.log(car instanceof Taxi);
console.log(taxi instanceof Bike);
console.log(taxi.constructor === Car);
console.log(Object.getPrototypeOf(Taxi.prototype) === Car.prototype);
